RSpec.describe "TimekeepingSnapshots.entry isolation" do
  it "entry built twice shares no mutable state between calls" do
    first = TimekeepingSnapshots.entry(id: 1, company_id: 3, version: 1, project_id: 5, user_id: 7)
    first["source_metadata"]["tool"] = "changed"
    first["note"] = "changed"

    second = TimekeepingSnapshots.entry(id: 1, company_id: 3, version: 1, project_id: 5, user_id: 7)

    expect(second).to include("source_metadata" => {}, "proof_metadata" => {}, "note" => "v1")
    expect(TimekeepingContract.load(:entry_snapshots).fetch("entry_fields")).not_to include("tool")
  end
end

