RSpec.describe "TimekeepingSnapshots.batch" do
  it "batch wraps items in the contract's batch_fields and schema_version, in the order given" do
    contract = TimekeepingContract.load(:entry_snapshots)
    first = TimekeepingSnapshots.item(TimekeepingSnapshots.entry(id: 1, company_id: 3, version: 1, project_id: 5, user_id: 7), generation: 1)
    second = TimekeepingSnapshots.item(TimekeepingSnapshots.entry(id: 2, company_id: 3, version: 1, project_id: 5, user_id: 7), generation: 1)

    batch = TimekeepingSnapshots.batch(first, second)
    empty = TimekeepingSnapshots.batch

    expect(batch.keys).to match_array(contract.fetch("batch_fields"))
    expect(batch).to eq("schema_version" => contract.fetch("schema_version"), "snapshots" => [first, second])
    expect(empty).to eq("schema_version" => contract.fetch("schema_version"), "snapshots" => [])
  end
end

require "rails_helper"

RSpec.describe "TimekeepingSnapshots batch accepted by SnapshotBatch" do
  it "a built batch parses through Timekeeping::SnapshotBatch with the values it was given" do
    entry = TimekeepingSnapshots.entry(id: 11, company_id: 3, version: 2, project_id: 5, user_id: 7,
                                       review_status: "approved", source: "cli", source_metadata: { "tool" => "codex" })
    batch = TimekeepingSnapshots.batch(TimekeepingSnapshots.item(entry, generation: 1, outbox_position: 1))

    item = Timekeeping::SnapshotBatch.parse(batch).sole

    expect([item.generation, item.outbox_position, item.entry_id, item.company_id, item.project_id]).to eq([1, 1, 11, 3, 5])
    expect(item.row).to include(
      "review_status" => TimesheetEntry.review_statuses.fetch("approved"),
      "source_metadata" => '{"tool":"codex"}', "duration" => 90.0, "work_date" => "2026-03-02"
    )
  end
end

