require "rails_helper"
require_relative "contract_example_helpers"

RSpec.describe TimekeepingSnapshots do
  include TimekeepingContractExampleHelpers

  it "snapshot_item still builds today's item with outbox_position defaulting to the version" do
    # The move to a shared builder "changes no behaviour": the item keeps the defaults it had before.
    item = snapshot_item(entry_id: 42, company: 2, version: 7, generation: 1, project: 5, user: 6)

    expected_entry = TimekeepingContract.load(:entry_snapshots).fetch("entry_fields").index_with(nil).merge(
      "id" => 42, "company_id" => 2, "version" => 7, "project_id" => 5, "user_id" => 6,
      "work_date" => "2026-03-02", "duration" => 90.0, "note" => "v7", "bill_status" => "unbilled",
      "review_status" => "not_required", "locked" => false, "source" => "manual", "source_metadata" => {},
      "proof_metadata" => {}, "created_at" => "2026-03-02T09:00:00Z", "updated_at" => "2026-03-02T09:00:00Z"
    )
    expect(item).to eq("generation" => 1, "outbox_position" => 7, "entry" => expected_entry)
    expect(described_class.item(described_class.entry(id: 42, company_id: 2, version: 7, project_id: 5, user_id: 6),
                                generation: 1)).to eq(item)
  end
end
